    def setup(self, graph):
        def directed_wheel(n):
            # bidirectional edges on the rim with directed edges to the central node
            G = nx.DiGraph(nx.cycle_graph(range(1, n)))
            G.add_node(0)
            G.add_edges_from((0, i) for i in range(1, n))
            return G

        self.graphs_dict = {}
        for n in self.nodes:
