            G = nx.DiGraph(nx.cycle_graph(range(1, n)))
            G.add_node(0)
            G.add_edges_from((0, i) for i in range(1, n))
            return G

        self.graphs_dict = {}
        for n in self.nodes:
            self.graphs_dict[f"wheel_graph({n})"] = nx.wheel_graph(n)
            self.graphs_dict[f"directed_wheel({n})"] = directed_wheel(n)'}

